  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://evilgoods.com/pages/over-1-7-million-already-paid-to-affiliates', 'brand_site', 'affiliate_program', 'Evil Goods'' own affiliate page (fetched) states a 20% base commission on every sale regardless of volume, rising to 25% at $5,000+ in monthly sales and up to 30% during product launches, with lifetime commission on customers a creator refers and 20% recurring commission on subscription orders for 3 months. It also states a 60-day cookie, monthly payouts with a $50 minimum, a 15% follower discount code, applications reviewed within 48 business hours, and an affiliate contact email (help@evilgoods.com). No statement about an earnings cap appears anywhere on the page, so commission_cap is recorded as unknown, not uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://evilgoods.com/pages/over-1-7-million-already-paid-to-affiliates', 'brand_site', 'brand_overview', 'The same page (fetched) says ''Join 2,500+ affiliates'' and claims over $1.7 million already paid to affiliates and 400,000+ customers. A published affiliate count of 2,500+ is absolute evidence of a large creator pool (compare Paula''s Choice at 1,607 recorded high in an earlier batch), so creator_saturation is recorded as high. The brand''s marketing is hype-heavy and its earnings claims are self-reported, which tempers the credibility score.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 16, 18, 13, 9, 3, '["20% base commission with lifetime customer commission, published on the brand''s own page", "Published affiliate contact email and 48-hour application review", "2,500+ affiliates stated by the brand, so the program is already crowded", "Self-reported earnings claims are hype-heavy and unverified, lowering credibility"]'::jsonb);
