  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://rateful.ai/brand/danessa-myricks-beauty', 'tiktok_shop_data', 'affiliate_program', 'Rateful''s TikTok Shop data page (fetched) confirms Danessa Myricks Beauty runs a TikTok Shop affiliate program: creators with TikTok Shop affiliate access add its products to their showcase and earn commission on every sale. It estimates $194K in sales in the 30 days to Nov 6, 2026 across 4,437 items at a $43.70 average price, with 94% of sales through affiliate creators'' videos and LIVEs, ranking the shop #336 in Beauty & Personal Care. TikTok Shop commission is set per product inside TikTok Shop and is not published on this page, so commission_rate is null and no cap statement exists, making commission_cap unknown.', 'publicly_reported', now());
