  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.flexoffers.com/affiliate-programs/thrive-causemetics-affiliate-program/', 'network_listing', 'affiliate_program', 'FlexOffers'' own program page for Thrive Causemetics (fetched) confirms an active affiliate program publishers can apply to, with promotional materials, tracking and a dedicated support team; it describes commission only as ''competitive'' and states a 1-day cookie duration. A separate InfluencerRate listing reports up to 10% commission and a 30-day cookie, which conflicts with the network page on the cookie and gives only a ceiling for the rate, so commission_rate is recorded as null with the conflict noted and commission_cap as unknown.', 'publicly_reported', now());
