  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.flexoffers.com/affiliate-programs/zitsticka-affiliate-program/', 'network_listing', 'affiliate_program', 'FlexOffers'' own program page for ZitSticka (fetched) states affiliates earn a 4% commission on sales made through their referrals and that the program offers a 30-day cookie duration, with promotional materials and tracking provided. Other routes list different figures (Lasso reports 3%, which reflects its Amazon-based listing, and Yazing offers members 5% cashback from its negotiated share), so the recorded 4% is specifically the FlexOffers network rate. No earnings-cap statement was found, so commission_cap is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 8, 6, 9, 4, '["Clear published network terms: 4% commission, 30-day cookie", "Single-focus acne niche suits before/after and routine content", "4% is a low rate versus DTC skincare norms"]'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Lo & Sons', 'https://www.loandsons.com', 'US direct-to-consumer bag brand founded by the Lo family, known for travel-light weekender bags, backpacks and work-to-gym bags that combine function and style. It recruits loyal customers, micro-influencers and large publishers into an affiliate program run through the Impact network.', 'United States', 'published') returning id into bid;
