  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'partnerships@loandsons.com', 'https://www.loandsons.com/pages/affiliate-sign-up', null, 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.loandsons.com/pages/affiliate-sign-up.', 'https://www.loandsons.com/pages/affiliate-sign-up', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Lo & Sons Affiliate Program (Impact)', null, null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.loandsons.com/pages/affiliate-sign-up', 'brand_site', 'affiliate_program', 'Lo & Sons'' own Affiliates page (fetched) invites loyal customers, micro-influencers and large-scale publishers to apply. Getting started: join through the Impact.com network (free), get approved, then search for Lo & Sons inside Impact to access text links and banners and earn commission on every referred bag purchase. Program questions go to partnerships@loandsons.com, published on the page. The brand''s own page publishes no commission rate and no earnings-cap statement, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopper.com/partnerships/loandsons-com-affiliate-program', 'affiliate_directory', 'affiliate_program', 'Shopper.com''s partnership listing (fetched) reports a 5% payout per sale for the Lo & Sons program, while affiliatesaz.com''s directory describes the Lo & Sons commission as ''varies by product''. Because the two fetched sources conflict and the brand itself publishes no rate, commission_rate is recorded as null with the conflict documented here. No fetched source states any earnings cap or creator count, so commission_cap and creator_saturation are unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 9, 14, 7, 5, '["Travel-light bags are a core, high-intent niche for travel and everyday-carry creators.", "The brand explicitly welcomes micro-influencers alongside large publishers, widening access for smaller creators.", "A published partnerships email and a clear Impact application path make the program easy to reach and verify.", "Commission rate is not published by the brand and directory reports conflict (5% vs varies by product), which caps the compensation score."]'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Solgaard', 'https://solgaard.co', 'Sustainable travel gear brand founded in 2016, known for suitcases, backpacks, watches and speakers made with ocean-bound plastic through its Solgaard x ShoreTide material program. It runs an affiliate program with a dedicated affiliate team, recruited by email application and paid monthly via FlexOffers.', 'United States', 'published') returning id into bid;
