  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Solgaard Affiliate Program (FlexOffers)', null, null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://solgaard.co/pages/become-an-affiliate', 'brand_site', 'affiliate_program', 'Solgaard''s own affiliate page (fetched) targets ''global citizens passionate about travel'' and offers ''a great commission structure, a dedicated affiliate team, regular deals and an easy-to-use affiliate platform''. Joining is by email application to solgaard@dmipartners.com with URLs, handles, audience stats and brand alignment. The page publishes no rate and no earnings-cap statement, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/solgaard/', 'affiliate_directory', 'affiliate_program', 'GetLasso''s program listing (fetched) reports 10% per sale with a 90-day cookie for Solgaard; LinkWhisper and AffiliateCollective independently report the same 10% rate and 90-day cookie, and a MaxFunnels review reports monthly payment via FlexOffers. The 10% rate is corroborated across three fetched sources, so it is recorded. No fetched source states an earnings cap or an absolute creator count, so commission_cap and creator_saturation are unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 13, 13, 7, 4, '["Sustainable luggage and backpacks sit squarely in the travel-gear niche, with a strong story angle around ocean plastic.", "A corroborated 10% commission with a long 90-day cookie is above average for travel gear.", "Application is a direct email to a named affiliate team, and the brand promises dedicated affiliate support.", "No earnings-cap statement is published, so the cap stays honestly unknown."]'::jsonb);
