  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'July Content Partner Affiliate Program', null, null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://july.com/nz/affiliate-program/', 'brand_site', 'affiliate_program', 'July''s own site (fetched) runs a ''Brand Affiliates'' page: ''Partner with us. Love July? Apply to become a content partner and earn commission on sales.'' The live page does not publish a rate or any earnings-cap statement, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affjumbo.com/new-offer-launched-july-affiliate-program/', 'affiliate_directory', 'affiliate_program', 'Published rates conflict across fetched sources: a mirrored copy of July''s affiliate page reports 8% on all luggage and accessories, rising to 9% on sales over $500 and 10% over $1,000 with a 45-day referral cookie, while older network directories report 4% (AffJumbo, 30-day cookie, 60-day hold) and 6% (Mopubi). Because the sources conflict, commission_rate is recorded as null with the conflict documented here. No fetched source states an earnings cap or creator count.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 10, 9, 6, 5, '["Design-led luggage is a proven, high-intent category for travel creators, and July is a recognised DTC brand in AU/NZ/US.", "July recruits content partners directly from its own site, signalling an active creator channel.", "Reported tiered rates up to 10% are attractive, but published figures conflict (4%, 6%, 8% tiered), so the rate is recorded as null and compensation is scored cautiously.", "No earnings-cap statement is published anywhere fetched, so the cap stays unknown."]'::jsonb);
