  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.bravodm.com/brands/pact', 'affiliate_directory', 'affiliate_program', 'BravoDM''s checked program facts (fetched; program checked October 2026) describe Pact''s affiliate program as a flat 8% commission, plus a separate Influencer Program the brand recruits for by invitation. AffJumbo''s listing independently reports the same flat 8% with a 30-day cookie and a $100 payout threshold, so the 8% rate is recorded. No fetched source states an earnings cap, so commission_cap is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://wearpact.com/campaign/influencer-signup', 'brand_site', 'creator_program', 'Pact''s own influencer signup page (fetched via the brand''s site) states the brand is ''currently revamping our influencer program'' and cannot accept new influencer applications at this time, with a relaunch planned within weeks. The affiliate route remains the open path; the influencer pause lowers the availability score. FlexOffers also lists a Pact Apparel affiliate program page. No creator count is published, so creator_saturation is unknown.', 'verified', now());
