  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://referralrocket.io/affiliate-program/alo-yoga_sB', 'affiliate_directory', 'affiliate_program', 'Published rates conflict across fetched sources: 14.4% via Impact (GetLasso and Creator Hero), 15.2% via FlexOffers (ReferralRocket) and 16% in another Creator Hero roundup. Because the figures conflict by network and none comes from the brand''s own published page, commission_rate is recorded as null with the conflict documented here. Alo''s creator culture is extensive, but no fetched source publishes an absolute creator count, so creator_saturation is unknown rather than guessed.', 'publicly_reported', now());
