  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://marketplace.referly.so/affiliate-programs/madewell', 'affiliate_directory', 'affiliate_program', 'Referly''s marketplace listing (fetched) reports a conflicting 1.5% commission for the same CJ-managed program (3-day cookie, monthly PayPal payouts, US market), and Shopper.com also lists 1.5%. Because fetched sources conflict between 5% and 1.5%, commission_rate is recorded as null with the conflict documented here. No absolute creator count is published, so creator_saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 8, 8, 7, 5, '["Denim-led mainstream fashion with a large, content-hungry audience and constant new-arrival cycles.", "Program is established on CJ Affiliate with a clear publisher signup path.", "The 3-day cookie is among the shortest in fashion, and published rates conflict (5% vs 1.5%), so compensation scores low.", "No earnings-cap statement is published, so the cap stays unknown."]'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Icebreaker', 'https://www.icebreaker.com', 'New Zealand-founded merino wool performance apparel pioneer (owned by VF Corporation), making plastic-free natural-fibre base layers, tees and outdoor clothing for travel and adventure. Regional affiliate programs are listed through FlexOffers.', 'New Zealand', 'published') returning id into bid;
