  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'FlexOffers', 2, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.flexoffers.com/affiliate-programs/icebreaker-australia-affiliate-program/.', 'https://www.flexoffers.com/affiliate-programs/icebreaker-australia-affiliate-program/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Icebreaker Affiliate Program (FlexOffers, regional)', null, null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.flexoffers.com/affiliate-programs/icebreaker-australia-affiliate-program/', 'affiliate_directory', 'affiliate_program', 'FlexOffers'' program page (fetched) lists regional icebreaker affiliate programs (Australia/New Zealand) promoting its merino ''move to natural'' apparel, with a 45-day cookie duration on the listed program. The FlexOffers listing publishes no commission rate. No fetched source states an earnings cap or creator count, so commission_cap and creator_saturation are unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://admin.shopper.com/partnerships/icebreaker-com-affiliate-program', 'affiliate_directory', 'affiliate_program', 'Shopper.com''s merchant listing (fetched) reports a 2% payout per sale for the Icebreaker program. It is a single directory figure with no corroborating second source, so it is recorded with publicly_reported confidence and should be re-verified inside the network before pitching.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 7, 7, 8, 5, '["Merino travel and outdoor apparel is a durable niche for travel and adventure creators, and Icebreaker is the category pioneer.", "A generous 45-day cookie on the listed regional program partly offsets a low reported 2% rate.", "The 2% figure rests on a single directory listing, so compensation is scored cautiously.", "No earnings-cap statement is published, so the cap stays unknown."]'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Kroma Wellness', 'https://www.kromawellness.com', 'Functional wellness brand selling superfood lattes, broths, porridges and a 5-day Reset program. Its own creator program, the Kroma Collective, gives members a unique 20%-off code plus referral link, pays 15% commission on first-time orders and 10% on repeat purchases, and states earnings are uncapped, paid monthly via PayPal.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'wellness'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://www.kromawellness.com/pages/ambassador', 'https://www.kromawellness.com/pages/ambassador', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Partnerize', 15, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.kromawellness.com/pages/ambassador.', 'https://www.kromawellness.com/pages/ambassador', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Kroma Collective Ambassador Program — 15% on first orders, uncapped earnings stated on the brand''s own page', 'https://www.kromawellness.com/pages/ambassador', 'https://www.kromawellness.com/pages/ambassador', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.kromawellness.com/pages/ambassador', 'official_site', 'affiliate', 'Kroma''s official Kroma Collective page, fetched in full: ''Uncapped earnings, paid monthly via PayPal. 15% on first-time orders, 10% on repeat purchases.'' Members get a unique 20% discount code + referral link, early access to launches and product rewards. The explicit ''Uncapped earnings'' statement on the brand''s own program page verifies commission_cap = uncapped. No creator count is published, so saturation stays unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.ascendpartner.com/affiliate/registration?refid=261816&referrer=RCT-KromaWellness', 'network_listing', 'affiliate', 'Ascend Partner (Partnerize) hosts the application for the ''Kroma Wellness Ambassador Program'', confirming the Collective recruits individual creators promoting on personal social media or blogs through a managed partnership platform.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 17, 18, 10, 9, 4, '["Functional lattes, broths and Reset programs are core wellness-creator content.", "A named creator community (the Collective) with ready-to-use content, messaging and templates supplied by the brand.", "15% first-order commission with an explicit ''Uncapped earnings'' statement on the brand''s own page \u2014 rare and verified; 10% on repeat purchases.", "Application runs through the brand''s own ambassador page and a Partnerize registration form; no public program email is published.", "Open application route for individual creators and wellness experts.", "Established premium wellness brand with named expert/creator members shown on the program page."]'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Clevr Blends', 'https://clevrblends.com', 'California beverage brand selling powdered SuperLatte mixes (matcha, chai, coffee, sleeptime) with functional ingredients. Its own Team Latte Lovers creator program gives approved creators a unique link and 15%-off code and pays 15% commission on every order placed with the link or code; the brand notes space in the program is limited.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'food-drink'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://clevrblends.com/pages/community', 'https://clevrblends.com/pages/community', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Own creator program', 15, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://clevrblends.com/pages/community.', 'https://clevrblends.com/pages/community', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Team Latte Lovers Creator Program — 15% commission on every order via personal link/code', 'https://clevrblends.com/pages/community', 'https://clevrblends.com/pages/community', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://clevrblends.com/pages/community', 'official_site', 'affiliate', 'Clevr''s official Community page, fetched in full: ''Join Team Latte Lovers! STEP 1: If approved (space is limited!), you''ll receive a unique link + code for 15% off Clevr Blends products. STEP 3: You earn 15% commission on every order placed using your link or code!'' Perks include a personal 15%-off code and VIP launch access. No earnings-cap statement and no creator count are published (''space is limited'' is not an absolute count), so cap and saturation stay unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://merchants.sovrn.com/merchants/167162/clevr-blends-affiliate-program', 'network_listing', 'affiliate', 'Sovrn Commerce also lists Clevr Blends as a merchant for publisher link monetization, but could not verify a rate; the brand''s own 15% program terms are the authoritative route.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 14, 9, 8, 5, '["Superfood lattes are staple food/wellness creator content with strong recipe and ritual formats.", "A structured own-brand creator team with codes, links and VIP campaign access built for recurring UGC.", "15% on every order is a strong published food/drink rate; no cap statement is published, so the cap is honestly unknown.", "Application is via the brand''s own community page; no public program email is published.", "Approval-based with limited space, which slightly reduces open availability.", "Well-known brand (Oprah''s Favorite Things history, national retail) with an established creator community."]'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Alice Mushrooms', 'https://alicemushrooms.com', 'Functional mushroom chocolate brand (focus, energy and sleep chocolates with nootropics and adaptogens). Its own affiliate program, run on Refersion, pays 15% commission on every order through an affiliate''s link or personal discount code, gives affiliates 40% off personal orders, and contacts accepted applicants from affiliate@alicemushrooms.com; influencer applicants need a minimum of 5K Instagram followers and must be US residents.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'wellness'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', 'affiliate@alicemushrooms.com', 'https://alicemushrooms.com/pages/affiliate', 'https://alicemushrooms.com/pages/affiliate', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Refersion', 15, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://alicemushrooms.com/pages/affiliate.', 'https://alicemushrooms.com/pages/affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Alice Mushrooms Affiliate Program — 15% commission via Refersion link or personal code', 'https://alicemushrooms.com/pages/affiliate', 'https://alicemushrooms.com/pages/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://alicemushrooms.com/pages/affiliate', 'official_site', 'affiliate', 'Alice Mushrooms'' official affiliate page, fetched in full: ''You will earn 15% commission for every order purchased through your affiliate link or any order that uses your personal discount code.'' Tracking and payout run through a Refersion dashboard with PayPal linked for payment; affiliates get 40% off personal orders. Accepted applicants are contacted via affiliate@alicemushrooms.com. Influencer applicants need a minimum of 5K followers on Instagram; open to US residents. No earnings-cap statement and no creator count are published, so cap and saturation stay unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 16, 14, 15, 7, 4, '["Functional mushroom chocolates sit squarely in the wellness/supplement creator niche.", "A dedicated affiliate program with personal codes pushed into bios and Linktrees \u2014 built for creator UGC.", "15% on every order is a strong published wellness rate; no cap statement published, so cap stays unknown.", "The brand publishes a dedicated program email (affiliate@alicemushrooms.com) and its own application pages.", "A 5K-follower minimum and US-residency rule gate smaller creators.", "Recognized functional-food brand with national press and retail presence."]'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('TRUFF', 'https://www.truff.com', 'Luxury truffle-infused hot sauce and pantry brand. Its affiliate program on ShareASale pays 10% per sale with a 30-day cookie (average order value about $54 in network listings), and the brand''s affiliate agency Acceleration Partners states the program offers up to 12% commission for content partners.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'food-drink'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'Michelle@TRUFF.com', null, 'https://boostedaffiliate.com/listings/programs/truff/', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'ShareASale', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://linkclicky.com/affiliate-program/truff/.', 'https://ui.awin.com/merchant-profile/92505', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'TRUFF Affiliate Program — 10% per sale on ShareASale, up to 12% for content partners', 'https://ui.awin.com/merchant-profile/92505', 'https://linkclicky.com/affiliate-program/truff/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/truff/', 'network_listing', 'affiliate', 'Network directory listing for TRUFF''s program: ShareASale platform, 10% per sale, 30-day cookie, all regions. Boosted Affiliate''s ShareASale-sourced listing corroborates 10%, a 30-day cookie, $54.02 AOV and names the program contact Michelle@TRUFF.com. No earnings-cap statement and no creator count are published, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.accelerationpartners.com/resources/truff-selects-acceleration-partners/', 'agency', 'affiliate', 'Acceleration Partners, the agency TRUFF selected to manage its affiliate program, states the program ''offers up to 12% commission'' for affiliates, particularly content partners — so 10% is recorded as the base rate with up to 12% available.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 12, 13, 9, 5, '["Premium pantry staples are proven food-creator content with strong gifting and recipe angles.", "A professionally managed program (Acceleration Partners) explicitly courting content partners.", "10% base with up to 12% published by the brand''s own agency, on a ~$54 average order; cap not stated, so unknown.", "A named affiliate-program contact email (Michelle@TRUFF.com) appears in the network listing.", "Open enrollment through ShareASale/Awin.", "Widely distributed premium brand sold nationally, including major grocery and specialty retail."]'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Momofuku Goods', 'https://momofuku.com', 'Pantry brand from David Chang''s Momofuku restaurant group, selling air-dried noodles, chili crunch, sauces and seasoned salts. It runs an affiliate program listed on CJ Affiliate at 10% per sale, plus a Collabs program on its own store offering commission on orders, monthly gifts and discount codes for partners.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'food-drink'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://canadashop.momofuku.com/pages/collab', 'https://canadashop.momofuku.com/pages/collab', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'CJ Affiliate', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://linkclicky.com/affiliate-program/momofuku/.', 'https://canadashop.momofuku.com/pages/collab', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Momofuku Goods Affiliate & Collabs Program — 10% per sale via CJ, plus own-store Collabs commissions', 'https://canadashop.momofuku.com/pages/collab', 'https://linkclicky.com/affiliate-program/momofuku/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/momofuku/', 'network_listing', 'affiliate', 'Network directory listing for Momofuku: CJ Affiliate platform, 10% commission per sale for the consumer-products (Goods) business. No earnings-cap statement and no creator count are published, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://canadashop.momofuku.com/pages/collab', 'official_site', 'affiliate', 'Momofuku Goods'' own Collabs page states partners can expect ''commission on orders you direct to our site, monthly gifts, and exclusive access to products we''re developing'', with partnership opportunities listed as affiliate marketing, gifting and discount codes.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.reacherapp.com/customers/momofuku', 'agency_case_study', 'creator_program', 'Reacher''s customer story confirms Momofuku Goods runs an actively managed creator/affiliate program with ongoing creator recruitment, cohort reporting and sample seeding — evidence of a live, staffed creator channel.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 15, 11, 9, 8, 5, '["Chili crunch and noodle content is a proven viral food-creator category, and the brand is built by a celebrity chef.", "An actively managed creator program with dedicated agency support, sampling and cohort recruitment.", "10% per sale is a fair published grocery rate; no cap statement published, so cap stays unknown.", "Partnerships route through the brand''s own Collabs page and CJ; no public partnerships email is published.", "Open affiliate enrollment plus an application-based Collabs track.", "One of the most recognized chef brands in the US, with national grocery distribution."]'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Kencko', 'https://www.kencko.com', 'Organic instant fruit and vegetable smoothie brand (freeze-dried produce, just add water or milk). It runs an affiliate program on Impact listed at 10% per sale, and its own Ambassador program (via the BrandBassador app) where accepted creators get a welcome product pack and a personal discount code and earn commission on every qualifying purchase.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'food-drink'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://www.kencko.com/pages/become-an-ambassador', 'https://www.kencko.com/pages/become-an-ambassador', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://linkclicky.com/affiliate-program/kencko/.', 'https://www.kencko.com/pages/become-an-ambassador', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Kencko Ambassador & Affiliate Program — 10% per sale via Impact, own ambassador track with product pack', 'https://www.kencko.com/pages/become-an-ambassador', 'https://linkclicky.com/affiliate-program/kencko/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.kencko.com/pages/become-an-ambassador', 'official_site', 'affiliate', 'Kencko''s official ambassador page: ''As a kencko Ambassador, you can earn commission when you share your passion for organic produce!'' Accepted ambassadors receive a pack of best-selling smoothies and a unique discount code, and ''every time someone uses your personal discount code for a purchase, you''ll earn a commission'', with extra rewards for content missions. Applications run through the BrandBassador app; creators must be active on Instagram, TikTok and/or YouTube. The page does not publish a rate, an earnings cap, or a creator count.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/kencko/', 'network_listing', 'affiliate', 'Network directory listing for kencko: Impact affiliate platform, 10% commission per sale. The 10% Impact rate is recorded as the program''s published rate; the brand''s own ambassador page confirms commission without restating the percentage.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 11, 9, 9, 4, '["Fruit-and-veg smoothie content fits health, wellness and busy-lifestyle creators directly.", "A structured ambassador program with content missions, welcome product and code-based commission \u2014 built for UGC.", "10% per sale published via Impact; the own ambassador page confirms commission but not the rate or any cap, so cap stays unknown.", "Application via the brand''s own ambassador page; no public program email is published.", "Two open routes (Impact and the ambassador app) for creators 18+ in the US, EU or UK.", "Established D2C brand with national US retail presence (Walmart) and a long-running program."]'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Fishwife', 'https://www.eatfishwife.com', 'Female-founded premium tinned seafood brand bringing European conservas culture to the US. Its affiliate program on ShareASale pays 10% per sale with a 30-day cookie, giving food creators a commission route on its tinned fish and seafood range.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'food-drink'), true);
