  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Fishwife Affiliate Program — 10% per sale on ShareASale with a 30-day cookie', null, 'https://linkclicky.com/affiliate-program/fishwife/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/fishwife/', 'network_listing', 'affiliate', 'Network directory listing for Fishwife: ShareASale platform, 10% commission per sale, 30-day cookie duration, all regions. A separate Yazing ambassador listing offers 3% of sales as a sub-affiliate route, which is lower than the direct ShareASale rate recorded here. No earnings-cap statement and no creator count are published, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 11, 8, 9, 5, '["Tinned fish is a breakout food-creator niche and Fishwife is its most visible US brand.", "An open network affiliate program suited to recipe and pantry content; the brand also runs influencer seeding.", "10% per sale with a 30-day cookie is a solid published grocery rate; cap not stated, so unknown.", "Joining is via ShareASale; no public partnerships email is published.", "Open network enrollment, all regions.", "Shark Tank-featured brand with national grocery distribution and strong press."]'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('UNREAL Snacks', 'https://www.unrealsnacks.com', 'Better-for-you candy brand making chocolate snacks with less sugar and no artificial ingredients, sold in 35,000+ US stores. Its affiliate program on ShareASale pays 9% per sale with a 7-day cookie; the brand also appears as a merchant on Impact.', 'United States', 'published') returning id into bid;
