  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 10, 8, 9, 5, '["Lower-sugar candy is high-performing snack content for food and family creators.", "Open network programs on two networks; the brand also runs paid creator ads recruiting snack reviewers.", "9% per sale is mid-band, and the 7-day cookie is short; cap not stated, so unknown.", "Joining is via the networks; no public partnerships email is published.", "Open enrollment on ShareASale and Impact.", "Sold in 35,000+ stores including Target, Costco and Whole Foods \u2014 strong brand credibility."]'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Grüvi', 'https://www.getgruvi.com', 'Toronto-founded brand of award-winning non-alcoholic craft beers and wines (its Golden Lager won the World Beer Cup gold for non-alcoholic beer). Its affiliate program runs on ShareASale with a 30-day cookie; published rate listings conflict (10% vs 15%), so no single rate is recorded.', 'Canada', 'published') returning id into bid;
