  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/grvi/', 'network_listing', 'affiliate', 'CONFLICTING RATES: LinkClicky''s ShareASale-sourced listing states Grüvi pays 15% per sale with a 30-day cookie, while Creator Hero''s and UpPromote''s program listings state 10% per sale with a 30-day cookie via the same ShareASale program (merchant ID 112482). Because the published sources conflict, commission_rate is recorded as null. No earnings-cap statement and no creator count are published, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 13, 8, 8, 9, 4, '["Non-alcoholic beer and wine is a fast-growing mindful-drinking niche for wellness and food creators.", "An open ShareASale program aimed at beverage influencers, with creator-program listings on multiple directories.", "Rate cannot be scored higher: published listings conflict between 10% and 15%, so the rate is honestly recorded as null; cap not stated, so unknown.", "Direct ShareASale merchant join link is published; no public partnerships email.", "Open network enrollment with a 30-day cookie.", "World Beer Cup gold-medal product credibility, though a smaller brand than national NA leaders."]'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Nutricost', 'https://nutricost.com', 'Utah-based supplements brand selling single-ingredient sports nutrition and everyday vitamins at budget prices, all third-party tested. Its affiliate program on Awin pays 6% commission with a 30-day cookie according to the official Awin merchant profile; a separate FlexOffers listing shows 4%.', 'United States', 'published') returning id into bid;
