  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/16896', 'network_listing', 'affiliate', 'Nutricost''s official Awin merchant profile states the program highlights: ''6% commission, 30 day cookie'', with exclusive affiliate and ambassador promotions in monthly newsletters. A separate FlexOffers listing shows 4% of online sales for its route — a different network''s terms, noted here; the Awin 6% is recorded as the primary published rate. No earnings-cap statement and no creator count are published, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 12, 7, 8, 9, 4, '["Budget supplements and creatine are constant fitness/wellness creator topics.", "The brand actively recruits ambassadors on social (code-based creator posts are common), and Awin runs ambassador promotions.", "6% is a low published rate for supplements, though the network profile is explicit; cap not stated, so unknown.", "Joining is via the Awin merchant profile; no public partnerships email is published.", "Open network enrollment with a 30-day cookie.", "Large Amazon-led supplement brand with third-party testing, but commodity positioning."]'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Dreo', 'https://www.dreo.com', 'Smart home air brand (tower fans, space heaters, air purifiers, humidifiers and air fryers) built around air comfort. Its affiliate program runs on CJ with a published standard commission, a 45-day cookie and a dedicated affiliate manager, and the brand also sells heavily through TikTok Shop creator videos.', 'United States', 'published') returning id into bid;
