  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Dreo Affiliate Program on CJ - 10% standard commission, 45-day cookie', 'https://www.affiliate-toolkit.com/program/dreo/', 'https://www.affiliate-toolkit.com/program/dreo/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affiliate-toolkit.com/program/dreo/', 'network', 'affiliate', 'Dreo''s CJ program details as reproduced from the network listing: ''standard commission 10, cookie duration 45 days, performance incentives 12 commission for actions >= 100, first sale bonus 10'', plus up-to-date banners, coupons and a dedicated affiliate manager. Recorded rate is the published 10% standard commission on CJ. No earnings-cap statement and no creator count are published, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.flexoffers.com/affiliate-programs/dreo-affiliate-program/', 'network', 'affiliate', 'FlexOffers lists a parallel Dreo route at 8% for online sales (9.6% at 100+ actions) with a 45-day cookie, confirming the 45-day window while showing per-network rates vary; the CJ standard 10% is the recorded figure.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://rateful.ai/brand/dreo', 'third_party', 'ugc', 'Rateful''s TikTok Shop data (estimates, not Dreo figures) reports about 94% of Dreo''s TikTok Shop sales in the 30 days to Nov 3, 2026 came through affiliate creators'' videos and LIVEs, showing a heavily creator-driven sales mix. It publishes no absolute creator count, so saturation stays unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 12, 8, 8, 4, '{"niche_fit": "Tower fans, heaters and purifiers are proven home-tech review and demo content with strong seasonal demand.", "ugc_evidence": "Creator-driven selling is core to the brand - most of its TikTok Shop sales are reported to come through affiliate creators.", "compensation": "Published 10% standard commission on CJ, rising to 12% at 100+ actions, with a 45-day cookie; no cap statement published.", "contact_access": "One route in: the CJ application. No verified affiliate email could be confirmed from a fetched page.", "opportunity_availability": "Program is live on CJ with a first-sale bonus and a dedicated manager per the listing.", "credibility": "Consistent 45-day cookie across network listings; rates vary by network (8% FlexOffers vs 10% CJ), which is normal multi-network practice."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('COSORI', 'https://www.cosori.com', 'VeSync kitchen appliance brand best known for air fryers, multi-cookers, kettles and coffee makers, sold across Amazon, Target and Walmart. Its own affiliate page recruits content creators, food bloggers and influencers with a 30-day last-click cookie and USD payments.', 'United States', 'published') returning id into bid;
