  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://cosori.com/pages/affiliates.', 'https://cosori.com/pages/affiliates', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'COSORI Affiliate Program - up to 10-15% published ceilings (conflicting), 30-day cookie', 'https://cosori.com/pages/affiliates', 'https://cosori.com/pages/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://cosori.com/pages/affiliates', 'official_site', 'affiliate', 'COSORI''s own affiliate page fetched in full. The hero panel states ''Earn up to 15% commission on every qualifying sale'', while the page''s own FAQ answers the commission question with ''Affiliates can earn up to 10% commission on every qualifying sale''. The FAQ also states a 30-day last-click cookie, free joining for creators/bloggers/influencers, and payment locked 27 days after month end and issued 20 days later in USD. Because the brand''s own page publishes two different ceilings (15% vs 10%), the rate is recorded as null with the conflict documented rather than guessed.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/cosori/', 'network', 'affiliate', 'Network directories disagree on COSORI''s route: LinkClicky lists CJ Affiliate at 3%-10% per sale, while affiliate-forum reporting describes an Awin PPS program at 5%-10%. Awin is recorded as the network with the conflict noted; no cap statement or creator count is published anywhere fetched.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 15, 9, 8, 9, 4, '{"niche_fit": "Air fryers and small kitchen appliances are evergreen creator content - recipes, tests and comparisons.", "ugc_evidence": "The brand''s own page expressly recruits content creators, food bloggers, recipe sites and influencers.", "compensation": "No single rate can be recorded: the brand''s own page conflicts with itself (up to 15% hero vs up to 10% FAQ), so the rate is honestly null; 30-day cookie confirmed.", "contact_access": "One route in: the application linked from the brand''s own affiliate page. No published affiliate email.", "opportunity_availability": "Program is live and free to join per the brand''s page.", "credibility": "Major retail presence (Amazon, Target, Walmart) under VeSync; the self-conflicting rate copy is the only blemish and is documented."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Waterdrop', 'https://www.waterdropfilter.com', 'Water purification brand founded in 2015 - refrigerator filters, reverse-osmosis systems, pitchers and under-sink filtration across 200+ products. Its affiliate program runs on Awin, CJ and Admitad with a 45-day cookie and performance incentives.', 'United States', 'published') returning id into bid;
