  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Waterdrop Affiliate Program on Awin - up to 10% ceiling, 45-day cookie', 'https://www.affiliate-toolkit.com/program/waterdrop/', 'https://www.affiliate-toolkit.com/program/waterdrop/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affiliate-toolkit.com/program/waterdrop/', 'network', 'affiliate', 'Waterdrop''s program description as carried on its network listings: ''commission up to 10 with performance incentives and special promotion opportunities, high unit price, 45 day cookie duration'', free to join, with Awin, CJ and Admitad all carrying the program (Awin is the primary join route). ''Up to 10%'' is a ceiling, not a base rate, and other routes report different figures (FlexOffers 6.4%, Yazing 8%), so the rate is recorded as null with the spread documented. No earnings-cap statement and no creator count are published.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.flexoffers.com/affiliate-programs/waterdrop-affiliate-program/', 'network', 'affiliate', 'FlexOffers lists the Waterdrop program at 6.4% on online sales with a 30-day cookie, a materially different figure from the ''up to 10%'' program headline - part of the rate conflict documented in the main evidence entry.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 11, 9, 7, 8, 4, '{"niche_fit": "Home water filtration is steady home-improvement and wellness content; RO systems carry high order values.", "ugc_evidence": "The program courts publishers broadly with banners, coupons and a monthly newsletter, but publishes no creator-specific program page.", "compensation": "Only a ceiling is published (''up to 10%'') and network routes conflict (6.4%-8%), so the rate is honestly null; 45-day cookie is a plus.", "contact_access": "Network applications only (Awin/CJ/Admitad); no verified affiliate email could be confirmed from a fetched page.", "opportunity_availability": "Live on three networks and free to join per the program description.", "credibility": "Established 2015 brand with 200+ products and consistent multi-network presence."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('iSpring Water Systems', 'https://www.ispringfilter.com', 'Residential water filtration specialist - reverse-osmosis, whole-house and under-sink systems with a $220+ average order value. Its own affiliate page openly recruits creators and influencers alongside publications, with on-time payments and a stated average order value.', 'United States', 'published') returning id into bid;
