  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'iSpring Water Systems Affiliate Program - up to 10% ceiling, $220+ AOV, rate reports conflict', 'https://www.ispringfilter.com/pages/affiliate', 'https://www.ispringfilter.com/pages/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.ispringfilter.com/pages/affiliate', 'official_site', 'affiliate', 'iSpring''s own affiliate page fetched in full: ''Competitive Commission Rates: Up to 10%'', ''30-Day Cookie Tracking'', ''$220+ Average Order Value'', on-time payments, and a partner section that expressly welcomes ''Creators & Influencers - anyone with a social media presence''. The page also markets ''$10K+ Monthly Earning Potential'' - that is a potential claim, not a statement that earnings are uncapped, so the cap stays unknown under the strict filter. Third-party reporting of the portal''s terms conflicts on the actual rate (8% on first purchases per SimplyCodes'' reading of the affiliate portal vs 10% per initial sale per Way2Earning, which also reports a 90-day cookie against the page''s 30 days), so the rate is recorded as null with the conflict documented.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 13, 9, 8, 8, 4, '{"niche_fit": "RO and whole-house filtration installs are strong DIY/home content, and the $220+ AOV lifts per-sale value.", "ugc_evidence": "The brand''s own page has a dedicated Creators & Influencers partner lane, not just publisher recruitment.", "compensation": "Ceiling-only on the brand page (''up to 10%'') and conflicting third-party rate reports (8% vs 10%), so the rate is honestly null.", "contact_access": "One route in: the brand''s own affiliate page and portal. No published affiliate email.", "opportunity_availability": "Program is live and free to join per the brand''s page.", "credibility": "Long-running filtration brand; the ''$10K+ monthly earning potential'' marketing line is noted but correctly not treated as a no-cap statement."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('LifeStraw', 'https://www.lifestraw.com', 'Water filtration brand for home, travel and emergency use - personal straws, pitchers and dispensers - with a Give Back model that funds a year of safe water for a child with every product sold. Its affiliate program joins through Impact or Shopify Collabs.', 'United States', 'published') returning id into bid;
