  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://lifestraw.com/pages/affiliate-program.', 'https://lifestraw.com/pages/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'LifeStraw Affiliate Program on Impact / Shopify Collabs - rate not published by the brand', 'https://lifestraw.com/pages/affiliate-program', 'https://lifestraw.com/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://lifestraw.com/pages/affiliate-program', 'official_site', 'affiliate', 'LifeStraw''s own affiliate page: the program ''allows you to advertise LifeStraw products and receive commissions'', joining is free ''through Impact Radius or Shopify Collabs'', and the FAQ expressly states ''the page does not list specific commission rates''. Third-party reports conflict - Impact listings at 5% per sale (LinkClicky, CompareEPC), an 8% / 90-day-cookie report (BMF), and a legacy 10% / 30-day AvantLink listing - so the rate is recorded as null with the spread documented. No earnings-cap statement and no creator count are published.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 14, 8, 8, 9, 5, '{"niche_fit": "Home water pitchers plus travel/emergency filters span home, outdoor and preparedness creator niches.", "ugc_evidence": "Two creator-friendly join routes (Impact and Shopify Collabs) with ready marketing assets per the brand''s page.", "compensation": "The brand publishes no rate and third-party figures conflict (5% vs 8% vs 10%), so the rate is honestly null.", "contact_access": "Applications via Impact or Shopify Collabs from the brand''s page. No published affiliate email.", "opportunity_availability": "Free and open to join on both routes per the brand''s page.", "credibility": "Category-defining brand with a long-running Give Back program; terms are consistent apart from the unpublished rate."}'::jsonb);
