  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://support.steelseries.com/hc/en-us/articles/14819474302989-Sponsorship-or-Affiliate-Request.', 'https://support.steelseries.com/hc/en-us/articles/14819474302989-Sponsorship-or-Affiliate-Request', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'SteelSeries Affiliate Program on Impact - up to 8% ceiling; signup currently CLOSED', 'https://support.steelseries.com/hc/en-us/articles/14819474302989-Sponsorship-or-Affiliate-Request', 'https://support.steelseries.com/hc/en-us/articles/14819474302989-Sponsorship-or-Affiliate-Request', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://support.steelseries.com/hc/en-us/articles/14819474302989-Sponsorship-or-Affiliate-Request', 'official_site', 'affiliate', 'SteelSeries'' own support page fetched in full: ''We are not currently accepting new applications'' and ''Sorry, signup is closed for now.'' The FAQ states affiliates ''can earn up to 8% commission on the sale of all SteelSeries products'', commissions are ''paid through Impact Radius'', eligibility is streamers, YouTube personalities and gaming community managers, and questions go to affiliates@steelseries.com. ''Up to 8%'' is a ceiling and third-party reports vary (5%-10%), so the rate is recorded as null; the closed signup is the dominant fact for availability. No cap statement or creator count is published.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 8, 11, 2, 5, '{"niche_fit": "Esports-grade headsets and keyboards are core gaming-creator content with high branded search demand.", "ugc_evidence": "The program is built specifically for streamers and YouTube personalities, with a dedicated Impact dashboard.", "compensation": "Only a ceiling is published (''up to 8%'') and reports vary, so the rate is honestly null.", "contact_access": "Published affiliate email (affiliates@steelseries.com) plus the support-page route - better access than most closed programs.", "opportunity_availability": "Signup is closed to new applications per the brand''s own page - existing affiliates only until it reopens.", "credibility": "Category-leading brand since 2001 with consistent program reporting across sources."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Jiminy''s', 'https://jiminys.com', 'Berkeley-based sustainable dog food brand making kibble and treats from cricket and insect protein. It runs an Impact affiliate program for publishers and its own ''Chirper'' ambassador program on Club, where creators earn cash commission on their affiliate code plus mission rewards.', 'United States', 'published') returning id into bid;
