  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Jiminy''s Affiliate Program on Impact - 12% commission, 30-day cookie; Chirper ambassador tier on Club', 'https://jiminys.com/pages/ambassador-program', 'https://jiminys.com/pages/ambassador-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affi.io/m/jiminys', 'network', 'affiliate', 'Affi.io''s network index lists ''Jiminys on Impact.com'' with status Open. The program''s published terms as reproduced by AffJumbo: 12% commission across the board on eligible purchases, 30-day last-click cookie, $100 payout threshold (wire, PayPal, Payoneer), free to join, closed PPC policy, and the note that ''Jiminy''s only works with a limited number of high-quality sites'' - a quality bar, not an absolute creator count, so saturation stays unknown. Recorded rate is the 12% Impact figure. No earnings-cap statement is published.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://jiminys.com/pages/ambassador-program', 'official_site', 'ugc', 'Jiminy''s own Chirper ambassador page fetched in full: creators join on Club with ''no minimum followers'', pick social missions for store credit and free products, and ''GET 10% OFF AFFILIATE CODE - for every use it gets, you earn a CASH commission'', with higher tiers available. The cash percentage is not published on the brand''s page, so the recorded rate rests on the Impact terms in the network evidence.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 16, 13, 7, 8, 4, '{"niche_fit": "Insect-protein dog food is a distinctive sustainability story that pet creators can build content around.", "ugc_evidence": "Two creator routes: the Impact program plus a no-minimum-followers ambassador program with missions and a personal code.", "compensation": "Published 12% across the board on Impact with a 30-day cookie; ambassador cash rate is unpublished. No cap statement.", "contact_access": "Applications via Impact or the Club ambassador page; questions by Instagram DM per the brand''s page. No published email.", "opportunity_availability": "Impact program listed as Open; ambassador program openly recruiting.", "credibility": "Established Berkeley brand with retail distribution; terms consistently reported."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Chippin', 'https://chippinpet.com', 'Sustainable dog food and treats made with eco-friendly proteins (cricket, silver carp, algae), formulated with veterinarians and founded in 2019. It lists on ShareASale and runs its own creator programs (Pawbassador, Pawfessional) through an UpPromote portal.', 'United States', 'published') returning id into bid;
