  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'ShareASale', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://getlasso.co/affiliate/chippin-inc/.', 'https://af.uppromote.com/chipper-pet/register_aff', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Chippin Affiliate Programs - ShareASale listing vs own-portal offers conflict (20% vs 10% / $10 flat)', 'https://af.uppromote.com/chipper-pet/register_aff', 'https://af.uppromote.com/chipper-pet/register_aff', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/chippin-inc/', 'network', 'affiliate', 'Lasso''s program entry for Chippin, Inc. reports 20% per sale and links the ShareASale listing (merchant ID 100179). The brand''s own UpPromote portal, however, publishes different live offers - a 10% commission on first purchases via code/link in one program, and flat $10-per-first-order terms in its Pawbassador and Pawfessional programs - while Shopper reports 5-10%. With the brand''s own portal and the network listing in conflict, the rate is recorded as null with the spread documented. No earnings-cap statement and no creator count are published.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 14, 9, 7, 8, 3, '{"niche_fit": "Eco-protein dog treats are a clear sustainability angle for pet creators, similar to the insect-protein niche.", "ugc_evidence": "Named creator programs (Pawbassador, Pawfessional) with personal codes and community framing, plus a ShareASale listing.", "compensation": "Rates conflict across the brand''s own portal and network listings (20% vs 10% vs $10 flat), so the rate is honestly null.", "contact_access": "Open registration on the brand''s own portal; no published affiliate email.", "opportunity_availability": "Multiple live registration routes on the brand''s portal.", "credibility": "Small 2019-founded team; the conflicting published offers lower confidence until one rate is confirmed in-portal."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('PetSnowy', 'https://petsnowy.com', 'Smart pet appliance brand - SNOW+ self-cleaning litter box, pet air purifier, dryer box and app-connected fountains and feeders. It runs an Impact affiliate program and its own Creator & Media Program that recruits influencers through Upfluence with commissions up to 15% on eligible campaigns.', 'United States', 'published') returning id into bid;
