  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://petsnowy.com/pages/media-pr.', 'https://petsnowy.com/pages/media-pr', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'PetSnowy Creator & Media Program + Impact affiliate - up to 15% ceiling, base rate not published', 'https://petsnowy.com/pages/media-pr', 'https://petsnowy.com/pages/media-pr', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://petsnowy.com/pages/media-pr', 'official_site', 'ugc', 'PetSnowy''s own Media & PR page fetched in full: its Creator & Media Program offers creators ''up to 15% commission and special rewards'', early access to launches and gifts; influencers apply through Upfluence and media partners email the PR team at Support@petsnowy.com. The page showcases named creator collaborations (Girls and Their Cats, 911Studios, TechUtopia and others). ''Up to 15%'' is a ceiling, and one publishing affiliate reports actually earning 2%, so the rate is recorded as null with the conflict documented. No earnings-cap statement and no creator count are published.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/petsnowy/', 'network', 'affiliate', 'LinkClicky lists PetSnowy''s affiliate program on Impact at 15% per sale as the officially listed payout - consistent with the brand''s ''up to 15%'' ceiling but not a guaranteed base rate, which is why the recorded rate stays null.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 16, 9, 10, 8, 4, '{"niche_fit": "Self-cleaning litter boxes and pet appliances are high-ticket, highly demonstrable pet-tech content.", "ugc_evidence": "A named Creator & Media Program with showcased creator collaborations and an Upfluence application route, plus an Impact listing.", "compensation": "Only a ceiling is published (''up to 15%'') and a live affiliate reports 2%, so the rate is honestly null.", "contact_access": "Published PR email on the brand''s own media page plus the Upfluence route.", "opportunity_availability": "Creator program openly recruiting worldwide per the brand''s page.", "credibility": "Established smart-pet brand with mainstream review coverage; rate opacity is the main caveat."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('KittySpout', 'https://www.kittyspout.com', 'Cat hydration brand behind the KittySpout stainless-steel water fountain, claiming over 1,100,000 cat owners served. Its own affiliate program runs on Social Snowball with a personal link, an audience discount and VIP access to new drops.', 'United States', 'published') returning id into bid;
