  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Social Snowball', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.kittyspout.com/pages/affiliate-page.', 'https://www.kittyspout.com/pages/affiliate-page', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'KittySpout Affiliate Program on Social Snowball - published rates conflict (50% headline vs 18% steps)', 'https://www.kittyspout.com/pages/affiliate-page', 'https://www.kittyspout.com/pages/affiliate-page', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.kittyspout.com/pages/affiliate-page', 'official_site', 'affiliate', 'KittySpout''s own affiliate page fetched in full - and it conflicts with itself: the headline banner reads ''Earn 50% commission. Give your audience 20% off!'', while the page''s own step-by-step states ''Your audience gets 15% off'' and ''You earn 18% commission on every sale'', and the page''s image copy also says ''Earn 18 commission. Give your audience 15 off.'' Sign-up runs through Social Snowball (kittyspout.socialsnowball.io). Because the brand publishes two irreconcilable rates (50% vs 18%), the rate is recorded as null with the conflict documented. The ''1,100,000+ cat owners'' figure is a customer count, not a creator count, so saturation stays unknown; no cap statement is published.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 21, 15, 9, 7, 9, 3, '{"niche_fit": "A single-hero-product cat fountain is easy, focused content for cat creators, though the catalog is narrow.", "ugc_evidence": "Creator-built program page (''Made for Creators'') with named affiliates showcased and link-in-bio promotion guidance.", "compensation": "The brand''s own page conflicts with itself (50% headline vs 18% in the steps), so the rate is honestly null until confirmed in-portal.", "contact_access": "One route in: the Social Snowball sign-up linked from the brand''s page. No published affiliate email.", "opportunity_availability": "Open self-serve sign-up, live now.", "credibility": "Large claimed customer base, but the self-conflicting rate copy is a real caution flag and is documented."}'::jsonb);
